// Validation failure as checked -> forces handling that just rethrows
class InvalidOrderException extends Exception { /* ... */ }

Order validate(Order o) throws InvalidOrderException { /* ... */ }
Order place(Order o)    throws InvalidOrderException { return validate(o); } // ripples up
// Caller can't really 'recover' from bad input here -- it's a bug to fix.
